function utcDate(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))return null;const d=new Date(s+'T12:00:00Z');return Number.isNaN(d.getTime())?null:d}function stamp(d){return d?d.toISOString().slice(0,10):''}function fmt(s){const d=utcDate(s);return d?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC',weekday:'short'}).format(d):'Not entered'}function offsetDate(source,days,direction,type){let d=utcDate(source);if(!d)return '';let n=Number(days),step=direction==='before'?-1:1;if(!Number.isInteger(n)||n<0||n>3650)return '';if(type==='calendar'){d.setUTCDate(d.getUTCDate()+step*n)}else{while(n>0){d.setUTCDate(d.getUTCDate()+step);const wd=d.getUTCDay();if(wd!==0&&wd!==6)n--}}return stamp(d)}function rowDate(r){const base=r.base==='closing'?$('deadline-closing').value:r.base==='recovery'?r.recovery:r.base==='trigger'?r.trigger:$('deadline-effective').value;return r.override||(r.days!==''&&base?offsetDate(base,r.days,r.direction,r.type):'')}
