 ctx.fillStyle='#153c50';ctx.fillRect(3,3,1258,202);ctx.fillStyle='#e5c895';ctx.font='700 23px Arial';ctx.fillText('LIVE PREVIEW',45,79);ctx.fillStyle='#fff';ctx.font='700 52px Arial';ctx.fillText('Your timeline',45,151);
