 function b64(value){const bytes=new TextEncoder().encode(value);let text='';for(let i=0;i<bytes.length;i+=8192)text+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(text).replace(/.{1,76}/g,'$&\r\n').trim()}
